from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    def calculate_nesting_level(group: str) -> int:
        max_depth = 0
        current_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1
        return max_depth

    def is_valid_parentheses_group(group: str) -> bool:
        stack = []
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    nesting_levels = []
    groups = paren_string.split()

    for group in groups:
        if is_valid_parentheses_group(group):
            nesting_levels.append(calculate_nesting_level(group))

    return nesting_levels
